#!/usr/bin/env node
/*
 * test_encounters.js -- builds every encounter template (tools/encounter_catalog.json, generated by tools/gen_encounters.js)
 * through the real engine, from fight_<id> to the first action menu, and checks each slot against the catalog: type, name,
 * epithet, group, hit points, AC, attack bonus, resolve, opening range, and the fight's own morale/leader/non-lethal settings.
 * Then it ends the first template's fight on paper (one enemy down, one fled) and checks the story can count its group.
 */
"use strict";
const fs = require("fs");
const vm = require("vm");
const path = require("path");
process.chdir(path.join(__dirname, ".."));
global.fs = fs; global.path = path; global.require = require;
function load(file) { vm.runInThisContext(fs.readFileSync(file, "utf8"), { filename: file }); }
load("web/scene.js"); load("web/navigator.js"); load("web/util.js"); load("headless.js");
global.main = {}; global.delayBreakEnd = function () {};
load("web/mygame/mygame.js");
Scene.prototype.loadScene = function () {
  this.loadLines(fs.readFileSync("web/mygame/scenes/" + this.name + ".txt", "utf8"));
  this.loaded = true;
  if (this.executing) this.execute();
};
const sceneReturn = Scene.prototype.return;
Scene.prototype.return = function () {
  if (this.name === "combat" && (!this.temps.choice_substack || !this.temps.choice_substack.length) &&
      (!this.stats.choice_subscene_stack || !this.stats.choice_subscene_stack.length)) { this.finished = true; return; }
  return sceneReturn.apply(this, arguments);
};
Scene.prototype.choice = function () { this.finished = true; };
new Scene("startup", stats, nav, false).execute();
const base = Object.assign({}, stats);
global.__combatFixedRandom = true;

const catalog = JSON.parse(fs.readFileSync("tools/encounter_catalog.json", "utf8"));
const types = {};
JSON.parse(fs.readFileSync("tools/enemy_catalog.json", "utf8")).types.forEach((t) => { types[t.id] = t; });
const ORD = ["first", "second", "third", "fourth", "fifth", "sixth"];

let failed = 0;
function expect(what, got, want) {
  if (String(got) !== String(want)) { failed++; console.error("FAIL " + what + ": got " + JSON.stringify(got) + ", want " + JSON.stringify(want)); }
}
function run(label, state, params) {
  const scene = new Scene("combat", state, nav, false);
  scene.loadScene();
  if (params) scene.temps.param = params;
  scene.goto(label);
  scene.execute();
  return state;
}

let firstState = null;
catalog.encounters.forEach(function (enc) {
  const state = Object.assign({}, base, { combat_no_morale: true });
  try { run("fight_" + enc.id, state); }
  catch (err) { failed++; console.error("FAIL " + enc.id + ": " + err.message); return; }
  const slots = [];
  enc.enemies.forEach(function (e) {
    const n = e.count || 1;
    for (let i = 0; i < n; i++) {
      const name = e.name || types[e.type].name;
      slots.push({ e: e, i: i, n: n, name: n > 1 ? name + " " + (i + 1) : name,
        epithet: e.epithet ? (n > 1 ? e.epithet.replace(/^the /, "the " + ORD[i] + " ") : e.epithet) : "the " + (n > 1 ? ORD[i] + " " : "") + name.toLowerCase(),
        group: e.group || name, range: Array.isArray(e.range) ? e.range[i] : e.range });
    }
  });
  const at = enc.id + " ";
  expect(at + "enemy count", state.combat_enemy_count, slots.length);
  expect(at + "morale off?", state.combat_no_morale, enc.morale === false);
  expect(at + "leader slot", state.combat_leader_slot, enc.leader || 0);
  expect(at + "non-lethal", state.combat_is_nonlethal, !!enc.nonlethal || (enc.nonlethal_slot === 1));
  slots.forEach(function (s, k) {
    const p = "combat_enemy" + (k + 1) + "_";
    const w = at + "slot " + (k + 1) + " ";
    expect(w + "type", state[p + "type_id"], s.e.type);
    expect(w + "name", state[p + "name"], s.name);
    expect(w + "epithet", state[p + "epithet"], s.epithet);
    expect(w + "group", state[p + "group"], s.group);
    if (s.e.hp !== undefined) expect(w + "max hp", state[p + "max_hp"], s.e.hp);
    if (s.e.ac !== undefined) expect(w + "ac", state[p + "ac"], s.e.ac);
    if (s.e.atk !== undefined) expect(w + "attack bonus", state[p + "atk_bonus"], s.e.atk);
    if (s.e.resolve !== undefined) expect(w + "resolve", state[p + "resolve"], s.e.resolve);
    if (s.range !== undefined) expect(w + "opening range", state[p + "range"], s.range);
    if (s.e.arrives !== undefined) expect(w + "arrives", state[p + "arrives"], s.e.arrives);
  });
  const left = Object.keys(state).filter((k) => /_override$/.test(k) && String(state[k]) !== String(base[k]));
  expect(at + "every override consumed", left.join(","), "");
  console.log("  ok  fight_" + enc.id + ": " + slots.map((s) => s.name).join(", "));
  if (!firstState) firstState = { enc: enc, state: state, n: slots.length };
});

if (firstState && firstState.n >= 3) {
  const s = firstState.state;
  s.combat_enemy1_hp = 0; s.combat_enemy2_hp = 0; s.combat_enemy3_out = "fled"; s.combat_enemy3_hp = 0;
  s.combat_active_target = 1; s.combat_enemy_hp = 0;
  run("combat_record_results", s);
  const group = firstState.enc.enemies[0].group || firstState.enc.enemies[0].name;
  run("count_results", s, [group, "down"]);
  expect("results: count_results " + group + " down", s.combat_result_n, 2);
  run("count_results", s, [group, "fled"]);
  expect("results: count_results " + group + " fled", s.combat_result_n, 1);
  expect("results: the group is cleared off the slot afterwards", s.combat_enemy1_group, "");
  console.log("  ok  after the fight, the story counts " + group + ": 2 down, 1 fled");
}
// REINFORCEMENTS: the first template with an "arrives" enemy.
const reinf = catalog.encounters.find((enc) => enc.enemies.some((e) => e.arrives));
if (reinf) {
  const slotOf = (function () { let n = 0, at = 0, round = 0; reinf.enemies.forEach((e) => { const c = e.count || 1; for (let i = 0; i < c; i++) { n++; if (e.arrives && !at) { at = n; round = e.arrives; } } }); return { slot: at, round: round }; })();
  const p = "combat_enemy" + slotOf.slot + "_";
  function fresh() { const st = Object.assign({}, base); run("fight_" + reinf.id, st); return st; }
  let st = fresh();
  expect("reinforcement: waits off the field", [st[p + "out"], Number(st[p + "hp"]), Number(st[p + "reserve_hp"]) === Number(st[p + "max_hp"]), Number(st[p + "arrives"])].join(), ["reserve", 0, true, slotOf.round].join());
  st.combat_round = slotOf.round - 1;
  run("combat_reinforcements_arrive", st, [false]);
  expect("reinforcement: not before its round", st[p + "out"], "reserve");
  st.combat_round = slotOf.round;
  run("combat_reinforcements_arrive", st, [false]);
  const edge = Number(st[p + "side"]) === -1 ? st.combat_lane_min_position : st.combat_lane_max_position;
  expect("reinforcement: on its round it arrives, HP back, on its own edge", [st[p + "out"], Number(st[p + "hp"]) === Number(st[p + "max_hp"]), Number(st[p + "position"]), st.combat_reinforcement_arrived].join(), ["", true, Number(edge), true].join());
  st = fresh();
  st.combat_leader_slot = 0;
  for (let k = 1; k <= Number(st.combat_enemy_count); k++) if (k !== slotOf.slot) st["combat_enemy" + k + "_hp"] = 0;
  st.combat_enemy_hp = 0;
  run("fight_check_all_dead", st);
  expect("reinforcement: the rest down early, it arrives at once and the fight goes on", [st.combat_all_enemies_dead, st[p + "out"], Number(st[p + "hp"]) > 0].join(), [false, "", true].join());
  if (reinf.leader) {
    st = fresh();
    st["combat_enemy" + reinf.leader + "_hp"] = 0;
    if (reinf.leader === 1) st.combat_enemy_hp = 0;
    run("fight_check_all_dead", st);
    expect("reinforcement: the leader down still ends the fight, and it never comes", [st.combat_all_enemies_dead, st[p + "out"]].join(), [true, "reserve"].join());
    run("combat_record_results", st);
    expect("reinforcement: never arrived, so it counts as standing", st["combat_result" + slotOf.slot + "_outcome"], "standing");
  }
  console.log("  ok  reinforcements: " + reinf.id + " slot " + slotOf.slot + " arrives on round " + slotOf.round);
}
if (failed) { console.error(failed + " encounter check(s) failed."); process.exit(1); }
console.log("Encounter templates OK: " + catalog.encounters.length + " built through the real engine and matching the catalog.");
